def transform(g):
    H,W=len(g),len(g[0])
    colors=sorted({v for r in g for v in r if v})
    order=sorted(colors,key=lambda c:min(j for i in range(H) for j in range(W) if g[i][j]==c))
    def shapes_of(g,color):
        H,W=len(g),len(g[0]); seen=set(); out=[]
        for i in range(H):
            for j in range(W):
                if g[i][j]==color and (i,j) not in seen:
                    st=[(i,j)]; seen.add((i,j)); cells=[]
                    while st:
                        y,x=st.pop(); cells.append((y,x))
                        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==color and (ny,nx) not in seen:
                                seen.add((ny,nx)); st.append((ny,nx))
                    ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                    y0,x0=min(ys),min(xs)
                    norm=[[0]*(max(xs)-x0+1) for _ in range(max(ys)-y0+1)]
                    for y,x in cells: norm[y-y0][x-x0]=color
                    out.append((min(ys),norm))
        return out
    cols=[]
    for c in order:
        sh=sorted(shapes_of(g,c))
        rows=[]
        for _,norm in sh:
            if rows: rows.append(None)
            rows.append(norm)
        mw=max(max(len(r) for r in n) for n in rows if n)
        out_rows=[]
        for n in rows:
            if n is None: out_rows.append([0]*mw); continue
            for r in n:
                pad=mw-len(r); l=pad//2
                out_rows.append([0]*l + r + [0]*(pad-l))
        cols.append(out_rows)
    out=[[0]*W for _ in range(H)]
    colx=0
    for rows in cols:
        y0=H-len(rows)
        for i,r in enumerate(rows):
            for j,v in enumerate(r):
                if v: out[y0+i][colx+j]=v
        colx+=max(len(r) for r in rows)+1
    return out

